import { Component, OnInit, TemplateRef, ViewChild } from '@angular/core';

import { NzButtonModule } from 'ng-zorro-antd/button';
import { NzCardModule } from 'ng-zorro-antd/card';
import { NzIconModule } from 'ng-zorro-antd/icon';

import { NxThoughtChainItem, NxThoughtChainModule } from 'ng-zorro-x/thought-chain';

@Component({
  selector: 'nx-demo-thought-chain-customization',
  imports: [NxThoughtChainModule, NzCardModule, NzButtonModule, NzIconModule],
  template: `
    <nz-card style="width: 500px">
      <nx-thought-chain [items]="nxItems" line="dashed" />
    </nz-card>

    <ng-template #createContent>
      <div style="display: flex; flex-direction: column; gap: 8px;">
        <!-- Think-like section (NxThink not yet implemented) -->
        <div class="nx-demo-think">
          <div class="nx-demo-think-header" (click)="thinkExpanded = !thinkExpanded">
            <nz-icon nzType="bulb" nzTheme="outline" style="color: #1677ff;" />
            <span>Thinking Process</span>
            <nz-icon nzType="right" nzTheme="outline" class="nx-demo-think-arrow" [nzRotate]="thinkExpanded ? 90 : 0" />
          </div>
          @if (thinkExpanded) {
            <div class="nx-demo-think-content">
              1. Analyze task, understand task workflow<br />
              2. Task creation, files needed for task<br />
              3. Task execution, using new component
            </div>
          }
        </div>

        <span style="color: rgba(0, 0, 0, 0.45);">Creating folder for new component</span>
        <nx-thought-chain-item variant="solid" icon="code" title="Executing command" description="mkdir -p component" />
        <span style="color: rgba(0, 0, 0, 0.45);">Creating files needed for new component</span>
        <nx-thought-chain-item variant="solid" icon="edit" title="Creating file" description="component/index.tsx" />
        <span style="color: rgba(0, 0, 0, 0.45);">Creating Chinese documentation file for new component</span>
        <nx-thought-chain-item
          variant="solid"
          icon="edit"
          title="Continue creating file"
          description="component/index.zh-CN.md"
        />
        <span style="color: rgba(0, 0, 0, 0.45);">Creating English description file for new component</span>
        <nx-thought-chain-item
          variant="solid"
          icon="edit"
          title="Continue creating file"
          description="component/index.en-US.md"
        />
      </div>
    </ng-template>

    <ng-template #checkContent>
      <div style="display: flex; flex-direction: column; gap: 8px;">
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="Folder creation completed"
          description="component"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.tsx"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.zh-CN.md"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.en-US.md"
        />
      </div>
    </ng-template>

    <ng-template #usedContent>
      <div style="display: flex; flex-direction: column; gap: 8px;">
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="Folder creation completed"
          description="component"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.tsx"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.zh-CN.md"
        />
        <nx-thought-chain-item
          variant="solid"
          status="success"
          title="File creation completed"
          description="component/index.en-US.md"
        />
      </div>
    </ng-template>

    <ng-template #footer>
      <button nz-button [nzBlock]="true">Thought Chain Item Footer</button>
    </ng-template>
  `,
  styles: `
    .nx-demo-think {
      display: flex;
      flex-direction: column;
      border-radius: 6px;
      background: rgba(0, 0, 0, 0.04);
      padding: 8px 12px;
    }
    .nx-demo-think-header {
      display: flex;
      align-items: center;
      gap: 8px;
      cursor: pointer;
      font-size: 14px;
      font-weight: 500;
    }
    .nx-demo-think-arrow {
      transition: transform 0.2s ease-in-out;
      margin-inline-start: auto;
    }
    .nx-demo-think-content {
      margin-block-start: 8px;
      font-size: 14px;
      color: rgba(0, 0, 0, 0.45);
      line-height: 1.6;
    }
  `
})
export class NxDemoThoughtChainCustomizationComponent implements OnInit {
  @ViewChild('createContent', { static: true }) createContentRef!: TemplateRef<void>;
  @ViewChild('checkContent', { static: true }) checkContentRef!: TemplateRef<void>;
  @ViewChild('usedContent', { static: true }) usedContentRef!: TemplateRef<void>;
  @ViewChild('footer', { static: true }) footerRef!: TemplateRef<void>;

  thinkExpanded = true;

  nxItems: NxThoughtChainItem[] = [];

  ngOnInit(): void {
    this.nxItems = [
      {
        title: 'Create Task',
        description: 'description',
        icon: 'heart',
        footer: this.footerRef,
        content: this.createContentRef
      },
      {
        key: 'check_task',
        title: 'Check Task Execution Steps Completion',
        icon: 'smile',
        collapsible: true,
        description: 'Verify the overall task execution logic and feasibility',
        content: this.checkContentRef
      },
      {
        key: 'used_task',
        title: 'Checking Task Execution Steps',
        description: 'Verify the overall task execution logic and feasibility',
        content: this.usedContentRef,
        status: 'error'
      }
    ];
  }
}
